fn size_for_entry(
    &self,
    filename: &Path,
    metadata: Option<&std::fs::Metadata>,
    file_type: &str,
    span: Span,
    signals: &Signals,
) -> Result<Value, ShellError> {
    let span = if self.listing_span != Span::unknown() {
        self.listing_span
    } else {
        span
    };
    if let Some(md) = metadata {
        let zero_sized = file_type == "pipe"
            || file_type == "socket"
            || file_type == "char device"
            || file_type == "block device";

        if md.is_dir() {
            self.directory_size_value(filename, md, span, signals)
        } else if md.is_file() {
            Ok(Value::filesize(md.len() as i64, span))
        } else if md.file_type().is_symlink() {
            if let Ok(symlink_md) = filename.symlink_metadata() {
                Ok(Value::filesize(symlink_md.len() as i64, span))
            } else {
                Ok(Value::nothing(span))
            }
        } else if zero_sized {
            Ok(Value::filesize(0, span))
        } else {
            Ok(Value::nothing(span))
        }
    } else {
        Ok(Value::nothing(span))
    }
}

